    def _fix_value(self):
        """Fix the card image for fixable non-standard compliance."""
        value = None
        keyword, valuecomment = self._split()
        m = self._value_NFSC_RE.match(valuecomment)

        # for the unparsable case
        if m is None:
            try:
                value, comment = valuecomment.split("/", 1)
                self.value = value.strip()
                self.comment = comment.strip()
            except (ValueError, IndexError):
                self.value = valuecomment
            self._valuestring = self._value
            return
        elif m.group("numr") is not None:
            numr = self._number_NFSC_RE.match(m.group("numr"))
            value = translate(numr.group("digt"), FIX_FP_TABLE, " ")
            if numr.group("sign") is not None:
                value = numr.group("sign") + value

        elif m.group("cplx") is not None:
            real = self._number_NFSC_RE.match(m.group("real"))
            rdigt = translate(real.group("digt"), FIX_FP_TABLE, " ")
            if real.group("sign") is not None:
                rdigt = real.group("sign") + rdigt

            imag = self._number_NFSC_RE.match(m.group("imag"))
            idigt = translate(imag.group("digt"), FIX_FP_TABLE, " ")
            if imag.group("sign") is not None:
                idigt = imag.group("sign") + idigt
            value = f"({rdigt}, {idigt})"
        self._valuestring = value
        # The value itself has not been modified, but its serialized
        # representation (as stored in self._valuestring) has been changed, so
        # still set this card as having been modified (see ticket #137)
        self._modified = True

    def _format_keyword(self):
        if self.keyword:
            if self.field_specifier:
                keyword = self.keyword.split(".", 1)[0]
                return "{:{len}}".format(keyword, len=KEYWORD_LENGTH)
            elif self._hierarch:
                return f"HIERARCH {self.keyword} "
            else:
                return "{:{len}}".format(self.keyword, len=KEYWORD_LENGTH)
        else:
            return " " * KEYWORD_LENGTH

    def _format_value(self):
        # value string
        float_types = (float, np.floating, complex, np.complexfloating)

        # Force the value to be parsed out first
        value = self.value
        # But work with the underlying raw value instead (to preserve
        # whitespace, for now...)
        value = self._value

        if self.keyword in self._commentary_keywords:
            # The value of a commentary card must be just a raw unprocessed
            # string
            value = str(value)
        elif (
            self._valuestring
            and not self._valuemodified
            and isinstance(self.value, float_types)
        ):
            # Keep the existing formatting for float/complex numbers
            value = f"{self._valuestring:>20}"
        elif self.field_specifier:
            value = _format_value(self._value).strip()
            value = f"'{self.field_specifier}: {value}'"
        else:
            value = _format_value(value)

        # For HIERARCH cards the value should be shortened to conserve space
        if not self.field_specifier and len(self.keyword) > KEYWORD_LENGTH:
            value = value.strip()

        return value

    def _format_comment(self):
        if not self.comment:
            return ""
        else:
            return f" / {self._comment}"

    def _format_image(self):
        keyword = self._format_keyword()

        value = self._format_value()
        is_commentary = keyword.strip() in self._commentary_keywords
        if is_commentary:
            comment = ""
        else:
            comment = self._format_comment()

        # equal sign string
        # by default use the standard value indicator even for HIERARCH cards;
        # later we may abbreviate it if necessary
        delimiter = VALUE_INDICATOR
        if is_commentary:
            delimiter = ""

        # put all parts together
        output = "".join([keyword, delimiter, value, comment])

        # For HIERARCH cards we can save a bit of space if necessary by
        # removing the space between the keyword and the equals sign; I'm
        # guessing this is part of the HIEARCH card specification
        keywordvalue_length = len(keyword) + len(delimiter) + len(value)
        if keywordvalue_length > self.length and keyword.startswith("HIERARCH"):
            if keywordvalue_length == self.length + 1 and keyword[-1] == " ":
                output = "".join([keyword[:-1], delimiter, value, comment])
            else:
                # I guess the HIERARCH card spec is incompatible with CONTINUE
                # cards
                raise ValueError(
                    f"The header keyword {self.keyword!r} with its value is too long"
                )

        if len(output) <= self.length:
            output = f"{output:80}"
        else:
            # longstring case (CONTINUE card)
            # try not to use CONTINUE if the string value can fit in one line.
            # Instead, just truncate the comment
            if isinstance(self.value, str) and len(value) > (self.length - 10):
                output = self._format_long_image()
            else:
                warnings.warn(
                    "Card is too long, comment will be truncated.", VerifyWarning
                )

